INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein höhenverstellbarer Schreibtisch allein ausreicht, um Rückenschmerzen zu verhindern?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Haltung und Pausen sind wichtig"}, {"text": "Ja", "correct": false, "because": "Einzelmaßnahme nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme hilft am besten, Augenbelastung am Bildschirm zu reduzieren?', 3, '[{"text": "Regelmäßige Blickpausen", "correct": true, "because": "Entlastet die Augenmuskulatur"}, {"text": "Höhere Bildschirmauflösung", "correct": false, "because": "Verbessert Klarheit, nicht Entlastung"}, {"text": "Größerer Monitor", "correct": false, "because": "Kann Belastung erhöhen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern eine gesunde Arbeitsumgebung im Büro?', 5, '[{"text": "Ergonomische Möbel", "correct": true, "because": "Unterstützen korrekte Haltung"}, {"text": "Ausreichende Beleuchtung", "correct": true, "because": "Vermeidet Augenbelastung"}, {"text": "Hohe Raumtemperatur", "correct": false, "because": "Kann Konzentration beeinträchtigen"}, {"text": "Lautes Radio", "correct": false, "because": "Stört Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Regelmäßige Pausen verbessern die Konzentration. b) Ein harter Stuhl fördert die Durchblutung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Harte Stühle können Schmerzen verursachen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich meinen Arbeitsplatz ergonomisch einrichte?', 4, '[{"text": "Monitorhöhe", "correct": false, "because": "Wichtig für Nackenbelastung"}, {"text": "Tastaturposition", "correct": false, "because": "Beeinflusst Handgelenke"}, {"text": "Bildschirmfarbe", "correct": true, "because": "Irrelevant für Ergonomie"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass man nur einmal täglich eine Pause machen muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Häufige kurze Pausen sind effektiver"}, {"text": "Ja", "correct": false, "because": "Zu selten für Prävention"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellung ist für einen Bürostuhl entscheidend?', 3, '[{"text": "Lendenstütze", "correct": true, "because": "Unterstützt die Wirbelsäule"}, {"text": "Feste Sitzfläche", "correct": false, "because": "Kann Druckstellen verursachen"}, {"text": "Hohe Lehne", "correct": false, "because": "Hilft, aber nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind für die Arbeit am Laptop wichtig?', 5, '[{"text": "Externe Tastatur", "correct": true, "because": "Verbessert Handhaltung"}, {"text": "Bildschirmerhöhung", "correct": true, "because": "Richtet Blick geradeaus"}, {"text": "Hohe Prozessorleistung", "correct": false, "because": "Irrelevant für Ergonomie"}, {"text": "Bunte Beleuchtung", "correct": false, "because": "Kein Gesundheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Blendung am Bildschirm schadet den Augen. b) Ein Ventilator ersetzt die Klimaanlage.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ventilatoren kühlen nicht ausreichend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Einrichtung eines Arbeitsplatzes unwichtig?', 4, '[{"text": "Beleuchtungsstärke", "correct": false, "because": "Beeinflusst Augenkomfort"}, {"text": "Sitzhöhe", "correct": false, "because": "Wichtig für Haltung"}, {"text": "Wandfarbe", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine ergonomische Maus nur für Rechtshänder sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Linkshänder verfügbar"}, {"text": "Ja", "correct": false, "because": "Modelle für beide Hände existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten schützt vor körperlichen Beschwerden?', 3, '[{"text": "Dynamisches Sitzen", "correct": true, "because": "Fördert Bewegung und Durchblutung"}, {"text": "Feste Sitzposition", "correct": false, "because": "Verursacht Verspannungen"}, {"text": "Ständiges Stehen", "correct": false, "because": "Belastet Beine"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Tageslichtlampen die Produktivität steigern. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Verbessert Stimmung und Fokus"}, {"text": "Nein", "correct": false, "because": "Nachweisbare Vorteile vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme priorisiere ich bei langen Arbeitszeiten?', 4, '[{"text": "Kurze Bewegungspausen", "correct": true, "because": "Verhindern Verspannungen"}, {"text": "Höhere Bildschirmhelligkeit", "correct": false, "because": "Belastet Augen"}, {"text": "Schnellere Tastatur", "correct": false, "because": "Kein Gesundheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine falsche Sitzhaltung schadet langfristig. b) Koffein ersetzt regelmäßige Pausen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Koffein kein Ersatz für Erholung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Stehpult?', 5, '[{"text": "Abwechslung der Haltung", "correct": true, "because": "Reduziert Rückenschmerzen"}, {"text": "Bessere Durchblutung", "correct": true, "because": "Fördert Bewegung"}, {"text": "Schnellere Arbeit", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Weniger Stromverbrauch", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Wahl eines Monitors unwichtig?', 3, '[{"text": "Blickabstand", "correct": false, "because": "Beeinflusst Augenkomfort"}, {"text": "Bildschirmgröße", "correct": false, "because": "Wichtig für Lesbarkeit"}, {"text": "Markenname", "correct": true, "because": "Funktion zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schadet langes Sitzen ohne Pausen der Gesundheit?', 2, '[{"text": "Ja", "correct": true, "because": "Verursacht Verspannungen und Kreislaufprobleme"}, {"text": "Nein", "correct": false, "because": "Nachweisbare Schäden vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Klimaanlage auch die Luftfeuchtigkeit regelt?', 3, '[{"text": "Ja", "correct": true, "because": "Vermeidet trockene Augen und Haut"}, {"text": "Nein", "correct": false, "because": "Viele Modelle entfeuchten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellung wähle ich für eine Tastatur, um Handgelenke zu schonen?', 4, '[{"text": "Leichte Neigung", "correct": true, "because": "Fördert natürliche Haltung"}, {"text": "Hohe Erhöhung", "correct": false, "because": "Belastet Gelenke"}, {"text": "Flache Position", "correct": false, "because": "Kann Spannung erzeugen"}]');
